  "criteria": {
    "definition": {
      "assessment": "sufficient",
      "reason": "迭代生成的动机、前向加噪关系、三种预测换算、条件对象与请求私有状态均有实质解释；也区分了最终交付与中间预览。成本部分的空间轴混用另列为阻塞问题。",
      "evidence": [
        {
          "path": "knowledge/models/image-diffusion.md",
          "quote": "请求状态至少包括当前 latent、所选时间步表中的位置、实际时间步、累计 alpha 数组、prediction_type、scheduler 配置、条件表示、guidance 设置、随机数生成器状态，以及使用多步求解器时的历史预测。"
        }
      ]
    },
    "legality": {
      "assessment": "partial",
      "reason": "预测类型、CFG 训练前提、固定条件缓存和近似复用边界解释充分，但 eta 的允许域未闭合。现有伪代码允许负 eta 通过平方根检查，却关闭其非零方差对应的随机项。",
      "evidence": [
        {
          "path": "knowledge/models/image-diffusion.md",
          "quote": "要求：N≥2；T 严格递减；对应 a 的取值合法；所有平方根的被开方数非负"
        },
        {
          "path": "knowledge/models/image-diffusion.md",
          "quote": "若 η＞0 且 σ²＞0：z ← NextGaussian(rng) 否则 z ← 0"
        }
      ]
    },
    "algorithm": {
      "assessment": "partial",
      "reason": "scheduler、guidance、随机流和请求提交顺序已展开，旧缓冲必须等待物理读者完成的要求正确。但 Fθ 仍是未展开的多层网络调用，正文及明确委托的阅读链没有给出从 latent 到逐层 hidden、条件注入、残差更新及输出预测的完整算法。",
      "evidence": [
        {
          "path": "knowledge/models/image-diffusion.md",
          "quote": "下面的伪代码把网络预测当成已定义的函数 Fθ，把 scheduler、条件缓存和随机状态显式放在请求状态中。"
        },
        {
          "path": "knowledge/models/image-diffusion.md",
          "quote": "raw_c ← Fθ(x,t,C_cond,cond_KV)"
        }
      ]
    },
    "cost": {
      "assessment": "partial",
      "reason": "MAC/FLOPs、显式 scores、权重流、准备、同步和峰值的计量边界总体清楚，24 GiB 与时延算例可复算。但预测通信与历史状态容量把 patch token 数当成 latent 空间点数，遗漏 p²；给定 p=2 时低估四倍。",
      "evidence": [
        {
          "path": "knowledge/models/image-diffusion.md",
          "quote": "token 数 T＝⌈H/(f p)⌉·⌈W/(f p)⌉"
        },
        {
          "path": "knowledge/models/image-diffusion.md",
          "quote": "一份预测约 4096·4·2＝32768 字节，即 32 KiB"
        },
        {
          "path": "knowledge/models/image-diffusion.md",
          "quote": "若保存 r 份 latent 形状状态，容量主项为 r T c_z b。"
        }
      ]
    },
    "adaptation": {
      "assessment": "partial",
      "reason": "分辨率、步数、容量与带宽、编译及 VAE 条件变化均有选择反转依据。但把 patch 变小时的模型函数列为保留关系不成立：原始 DiT 的 patch 输入投影及输出解码形状依赖 p，不能把改变 p 当成同一 checkpoint 的几何调整。",
      "evidence": [
        {
          "path": "knowledge/models/image-diffusion.md",
          "quote": "| patch 变小 | 模型函数和条件方式 | T 约按 patch 边长平方增长，self-attention 工作量快速增长；不能只按参数量判断 |"
        }
      ]
    },
    "diagnosis": {
      "assessment": "partial",
      "reason": "竞争解释、受控比较和反证修正有实质内容；未测 GPU 与质量效果的边界也声明清楚。但两个异常式负对照无法区分成功检错与检错失败，halo 测试也没有实现正文所称的少一个像素缺陷，故执行成功不能支撑当前负对照结论。",
      "evidence": [
        {
          "path": "knowledge/models/image-diffusion.md",
          "quote": "只有这些负对照被检查拒绝，正例通过才有区分力。"
        },
        {
          "path": "knowledge/models/image-diffusion.md",
          "quote": "VAE tile 的 halo 少一个像素，边界卷积应与全图参考不同。"
        }
      ]
    }
  },
  "findings": [
    {
      "id": "K-MODEL-009-COST-PATCH-LATENT",
      "criterion": "cost",
      "evidence": "正文定义“token 数 T＝⌈H/(f p)⌉·⌈W/(f p)⌉”，随后写“一份预测约 4096·4·2＝32768 字节，即 32 KiB”及“容量主项为 r T c_z b”。",
      "impact": "T 是 patch 化后的序列长度，c_z 是 patch 化之前的 latent 通道数。1024×1024、f=8、p=2 时，latent 为 128×128×4，BF16 一份预测为 131072 字节，即 128 KiB。当前公式低估通信和 solver 历史容量四倍，而且错误地使这些字节数随 patch 大小变化。",
      "blocking": true,
      "required_revision": "分别定义 latent 空间点数与 patch token 数。预测及历史状态按实际 latent shape 计量；整除条件下为 p²T c_z b 与 r p²T c_z b，非整除时明确 padding 和裁剪。修正 32 KiB 算例，并增加保持 latent 网格不变、改变 p 后预测字节数不变的检查。"
    },
    {
      "id": "K-MODEL-009-DIAG-NEGATIVE-CONTROLS",
      "criterion": "diagnosis",
      "evidence": "脚本 negative_wrong_v 中先执行 require(not close(x0_bad, x0) or not close(eps_bad, eps), 'wrong v sign was not detected')，随后无条件 raise CheckError('wrong v sign detected')；expect_reject 捕获任何 CheckError 都报告 rejected。negative_schedule 使用相同结构。tiled_conv 的 right 已含 stop + len(kernel) - 1 + halo，而 bad_tiled_conv 改为 signal[start:stop]。",
      "impact": "错误 v 被检测时抛异常，修复 v 后 require 失败也抛同类异常，两者都被报告为成功拒绝。本轮内存转写探针实际复现了这两种报告。因此远端 returncode=0 不能证明这些负对照有区分力。halo 负例则删除了整段卷积所需输入，输出长度已改变，并非正文所称少一个像素；正例读取范围即使去掉额外 halo 仍覆盖所需输入。",
      "blocking": true,
      "required_revision": "将检查框架自身失败与被测验证器拒绝缺陷分开；让同一验证器接受正确对象、拒绝注入缺陷的对象，失败断言必须传播为测试失败。修复 expect_reject 的异常混淆。分块测试按明确坐标定义必需 halo，注入少一个必需输入的缺陷，并对相同输出位置与全图参考比较。验证修复缺陷后不再被当作负例拒绝。"
    },
    {
      "id": "K-MODEL-009-ALG-DENOISER-BLACKBOX",
      "criterion": "algorithm",
      "evidence": "正文写“下面的伪代码把网络预测当成已定义的函数 Fθ”，算法核心为“raw_c ← Fθ(x,t,C_cond,cond_KV)”与“raw_u ← Fθ(x,t,C_null,null_KV)”。其他段落给出了 cross Q/K/V 和层成本，但没有展开 Fθ 的逐层输入与更新。",
      "impact": "读者可以实现 scheduler 外循环，却无法据当前明确交付的算法恢复代表性去噪网络，或定位每层条件缓存如何被消费。完整论文包含相关结构材料，但当前正文没有明确委托到一份完整算法说明，也没有说明逐层中间结果与整步 latent 提交的关系。",
      "blocking": true,
      "required_revision": "在当前范围内选择一种代表性网络，展开 latent 输入变换、时间与条件注入、逐层 attention/FFN 和残差更新、输出投影及恢复 latent shape 的数据流，标明每层固定缓存与每步临时状态。说明全部网络预测完成后才能进行 scheduler 更新和请求提交；其他结构可明确委托给已有完整算法说明，不要求枚举所有 checkpoint。"
    },
    {
      "id": "K-MODEL-009-LEGAL-ETA-DOMAIN",
      "criterion": "legality",
      "evidence": "算法要求只有“N≥2；T 严格递减；对应 a 的取值合法；所有平方根的被开方数非负”，方差使用“σ² ← η²·(1−a_s)/(1−a_t)·(1−a_t/a_s)”，噪声生成却限定“若 η＞0 且 σ²＞0”。",
      "impact": "例如 a_t=0.5、a_s=0.8、eta=-0.4 时，σ²=0.024、方向被开方数为 0.176，满足所列检查，但算法令 z=0，执行了与所写非零方差更新不同的函数。",
      "blocking": true,
      "required_revision": "明确本算法支持的 eta 数值域，并在初始化时检查有限性及范围。若只支持非负 eta，显式拒绝负值；增加能实际调用该验证分支的非法输入检查，不能仅依赖开方合法性。"
    },
    {
      "id": "K-MODEL-009-ADAPT-PATCH-CHECKPOINT",
      "criterion": "adaptation",
      "evidence": "条件变化表写“| patch 变小 | 模型函数和条件方式 |”。所供 DiT 原文明确输入逐 patch 线性嵌入，并将每个输出 token 解码为 p×p×2C。",
      "impact": "改变 p 通常同时改变输入投影和输出解码参数形状及模型函数，不能直接在同一普通 DiT checkpoint 上保留函数。当前表格容易使读者把架构与模型候选变化当成执行布局变化。",
      "blocking": true,
      "required_revision": "将该行限定为不同 patch 配置的模型候选比较，明确需要相容 checkpoint 或模型明确支持的可变 patch 机制；保留可沿用的扩散语义分析，同时重新核对权重、位置处理、输出还原和质量。"
    }
  ],
  "limitations": [
    "目标 GPU 的时间、实际 HBM 事务、workspace、浮点差异、异步完成与性能重叠均未验证；正文对此声明清楚，可继续作为 limitation。",
    "没有独立图像质量研究或 Agent 使用效果对照；Wan 的缓存收益仅核对为所供论文范围内的作者报告，不能外推为图像任务的实测收益。",
    "Diffusers 源码归档未暴露；本次依据所供 S-DIFFUSERS 算法说明核对，没有声称独立检查了源码。其整数回退策略与最终边界未被现有脚本对照。",
    "docs/knowledge-build-workflow.md 与技能文件未提供，当前工具也没有可用文件读取接口；本次按用户直接提供的 review JSON schema 交付，没有声称读取这些文件。"
  ],
  "checks": [
    {
      "script": "tools/check_k_model_009_full.py",
      "args": []
    }
  ],
  "no_checks_reason": "",
  "reading_scope": "完整阅读用户提供的全部候选正文、test_script、author_notes、actual_preflight 执行记录与材料正文。以下均为完整供给的抽取文本，范围单位为零起点、左闭右开字符：AGENTS.md [0,567)；docs/knowledge-method.md [0,2251)；docs/knowledge-review.md [0,3016)；knowledge/models/image-diffusion.md [0,12773)；knowledge/sources/S-LDM.md [0,494)；knowledge/sources/S-DIT.md [0,468)；knowledge/sources/S-DIFFUSERS.md [0,995)；knowledge/sources/S-WAN.md [0,487)；knowledge/models/video-generation.md [0,3900)；knowledge/algorithms/cross-attention-cache.md [0,3845)；knowledge/frameworks/compile-dynamic-shapes.md [0,4495)；knowledge/workloads/slo-goodput.md [0,2616)；knowledge/algorithms/parallelism.md [0,6115)；knowledge/system-semantics/memory-allocators.md [0,4191)；knowledge/tools/statistical-experiments.md [0,4269)；knowledge/models/speech-generation.md [0,3599)；references/S-LDM/fulltext.txt [0,101520)；references/S-DIT/fulltext.txt [0,56351)。tools/check_k_model_009_full.py 为 candidate.test_script 所供完整脚本，绑定给定哈希。仅阅读以下摘录，不将其列入 documents：knowledge/hardware/gpu-kernel-pipelines.md [0,500)、[4000,12000)；knowledge/system-semantics/design-synthesis.md [0,8500)；references/S-WAN/fulltext.txt [0,20000)、[36000,68000)、[88000,97613)、[104000,108000)、[112000,120000)、[128000,140000)、[148000,175801)。未读取未供给区间、PDF 图片、reader.html、源码归档或本轮产物目录；未执行文件链接存在性检查。",
  "test_assessment": "所供实际记录显示绑定脚本在 remote_bwrap 中以 Python 3.12、隔离参数执行，returncode=0，无 stderr、超时或输出制品；这建立了该脚本此次成功执行的事实。作者称本人未执行，协调侧提供远端执行记录，两者不矛盾。本 reviewer 没有 Python/终端执行接口，未把检查列表冒称为本人重新运行的结果；另外使用 functions.exec 执行了明确标为 JavaScript 内存转写的独立审查探针。三种预测换算测试以已知 x0、epsilon 和前向构造为参考，具有有效代数约束；容量与时间测试能核对给定算术，分块正例也确实对照了全图卷积。DDIM 随机项测试主要复用同一 sigma 和更新表达式，不是固定 scheduler 的独立实现参考。错误 v 与时间表负例的 CheckError 被框架无差别捕获，既能把正确检错报告 rejected，也能把检错失败报告 rejected；内存探针将 bad_v 改为正确公式后，仍实际得到 negative control rejected，暴露其假阳性。时间表负例只比较两个常量，没有调用真实时间点选择器。cross K/V 测试没有实际缓存查找或错误复用路径，仅比较两个已选不同向量的投影。halo 负例造成输出截短，未验证少一个必需像素的边界错误；移除正例人为 guard 后，内存探针发现 halo=2、1、0 均与全图参考一致，因为读取范围已额外包含完整 kernel reach。独立几何复算得到预测为 128 KiB，现有测试没有核对这一项。现有脚本还未覆盖 eta 非法域、完整多步推进、末步边界、裁剪重算分支、逐层网络数据流或真实缓存身份验证。未执行的 GPU、质量、链接和运行时检查不记为 PASS。"
}
